import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group, Mesh, IcosahedronGeometry, PlaneGeometry, Color, InstancedMesh,
    Matrix4, Vector3, Quaternion, Object3D, AdditiveBlending, DoubleSide,
    PointLight, DirectionalLight, AmbientLight, DynamicDrawUsage
  } = THREE;

  const group = new Group();
  group.name = 'particle-constellation-hero';

  const vs = config.intent?.visualSpec ?? {};
  const colors = vs.colors ?? {};
  const bg = new Color(colors.background ?? '#0b0b10');
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const fogColor = new Color('#0b0b10');

  // ---- Backdrop gradient plane (stage) ----
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide, depthWrite: false });
  backdropMat.colorNode = mix(
    vec3(bg.r, bg.g, bg.b),
    vec3(ink.r, ink.g, ink.b),
    uv().y
  );
  const backdrop = new Mesh(new PlaneGeometry(16, 10), backdropMat);
  backdrop.position.set(0, 0, -4.6);
  group.add(backdrop);

  // ---- Generate field positions (ellipsoidal shell 6 x 4 x 5 @ [0,0,-1.5]) ----
  const FIELD_COUNT = 1110;
  const CORE_COUNT = 90;
  const fieldPos = [];
  const fieldPhase = [];
  for (let i = 0; i < FIELD_COUNT; i++) {
    let x, y, z, s;
    do {
      x = (Math.random() * 2 - 1) * 3;
      y = (Math.random() * 2 - 1) * 2;
      z = (Math.random() * 2 - 1) * 2.5;
      s = (x * x) / 9 + (y * y) / 4 + (z * z) / 6.25;
    } while (s > 1);
    fieldPos.push(new Vector3(x, y, z - 1.5));
    fieldPhase.push(Math.random() * Math.PI * 2);
  }

  // ---- Core positions (0.5-radius sphere at origin) ----
  const corePos = [];
  const corePhase = [];
  for (let i = 0; i < CORE_COUNT; i++) {
    let x, y, z, s;
    do {
      x = (Math.random() * 2 - 1) * 0.5;
      y = (Math.random() * 2 - 1) * 0.5;
      z = (Math.random() * 2 - 1) * 0.5;
      s = x * x + y * y + z * z;
    } while (s > 0.25);
    corePos.push(new Vector3(x, y, z));
    corePhase.push(Math.random() * Math.PI * 2);
  }

  // Depth falloff + fog bake
  const opacityAtZ = (z) => {
    const o = 0.9 + 0.15 * Math.max(-5, Math.min(0, z));
    return Math.max(0.15, Math.min(0.9, o));
  };
  const fogAtZ = (z) => Math.min(0.8, Math.max(0, (-z - 0.5) / 4.5));

  const geo = new IcosahedronGeometry(0.012, 0);
  const sorted = fieldPos
    .map((p, i) => ({ p, ph: fieldPhase[i], z: p.z }))
    .sort((a, b) => a.z - b.z);

  const BUCKETS = 6;
  const bSize = Math.ceil(FIELD_COUNT / BUCKETS);
  const fieldMeshes = [];
  const primResults = [];
  const _o = new Object3D();

  for (let b = 0; b < BUCKETS; b++) {
    const slice = sorted.slice(b * bSize, (b + 1) * bSize);
    if (!slice.length) continue;
    const count = slice.length;
    let zSum = 0;
    for (const e of slice) zSum += e.z;
    const zC = zSum / count;
    const op = opacityAtZ(zC);
    const fogF = fogAtZ(zC);
    const col = new Color().copy(paper).lerp(fogColor, fogF);

    const mat = new MeshStandardNodeMaterial({
      color: col,
      metalness: 0,
      roughness: 1,
      emissive: new Color(col),
      emissiveIntensity: 0.9,
      transparent: true,
      opacity: op,
      depthWrite: false,
    });
    const im = new InstancedMesh(geo, mat, count);
    im.instanceMatrix.setUsage(DynamicDrawUsage);
    im.frustumCulled = false;
    for (let i = 0; i < count; i++) {
      _o.position.copy(slice[i].p);
      _o.scale.setScalar(1);
      _o.quaternion.identity();
      _o.updateMatrix();
      im.setMatrixAt(i, _o.matrix);
    }
    im.instanceMatrix.needsUpdate = true;
    im.userData.anchors = slice.map((e) => e.p.clone());
    im.userData.phases = slice.map((e) => e.ph);
    fieldMeshes.push(im);
    group.add(im);
  }

  // ---- Accent core (additive) ----
  const coreMat = new MeshStandardNodeMaterial({
    color: accent,
    metalness: 0,
    roughness: 1,
    emissive: new Color(accent),
    emissiveIntensity: 1.8,
    transparent: true,
    opacity: 1.0,
    depthWrite: false,
    blending: AdditiveBlending,
  });
  const coreMesh = new InstancedMesh(geo, coreMat, CORE_COUNT);
  coreMesh.instanceMatrix.setUsage(DynamicDrawUsage);
  coreMesh.frustumCulled = false;
  for (let i = 0; i < CORE_COUNT; i++) {
    _o.position.copy(corePos[i]);
    _o.scale.setScalar(1);
    _o.quaternion.identity();
    _o.updateMatrix();
    coreMesh.setMatrixAt(i, _o.matrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  coreMesh.userData.anchors = corePos.map((p) => p.clone());
  coreMesh.userData.phases = corePhase;
  group.add(coreMesh);

  // ---- Lights ----
  group.add(new AmbientLight(0xffffff, 0.6));
  const rim = new PointLight(accent.getHex(), 0.8, 25, 2);
  rim.position.set(0, 0.5, -1);
  group.add(rim);
